/**
 * Root-path aliases for the OAuth endpoints.
 *
 * Our endpoints live under `/oauth/*` and are advertised in the
 * authorization-server metadata. Claude's hosted connector, however, falls
 * back to the pre-discovery default endpoints of the 2025-03-26 MCP auth spec
 * — `<mcp-origin>/token`, `/register`, `/authorize` — when a refresh or a
 * discovery fetch fails transiently, and then never re-runs discovery: it
 * keeps posting to the default path until the user reconnects by hand
 * (anthropics/claude-ai-mcp#1169, reproduced by several operators). One blip
 * on our side would otherwise strand a connector on `POST /token` → 405.
 *
 * So the default paths answer exactly like the advertised ones: the request
 * is re-addressed in place (no redirect — a 30x on a token POST is not
 * something to bet a client on) before it reaches the OAuth provider.
 *
 * The three paths must also be in `run_worker_first` (wrangler.toml), or the
 * asset resolver answers them with the SPA shell / a 405 first.
 */

const ALIASES: Readonly<Record<string, string>> = {
  '/token': '/oauth/token',
  '/register': '/oauth/register',
  '/authorize': '/oauth/authorize'
}

/**
 * The request to hand to the OAuth provider: the same request re-addressed to
 * the advertised endpoint when it targets a default path, otherwise the
 * request itself (identity, so callers can skip work when nothing changed).
 */
export function aliasDefaultOAuthEndpoint(req: Request): Request {
  const url = new URL(req.url)
  const target = ALIASES[url.pathname]
  if (!target) return req
  url.pathname = target
  return new Request(url.toString(), req)
}

/**
 * True when `clientId` names a Client ID Metadata Document (an https URL with
 * a path) rather than a client registered in KV. Such a client_id is shared
 * by every installation of that client — and by every user.
 */
export function isCimdClientId(clientId: string): boolean {
  try {
    const u = new URL(clientId)
    return u.protocol === 'https:' && u.pathname !== '/' && u.pathname !== ''
  } catch {
    return false
  }
}

input.new_string:
accessTokenTTL: MCP_ACCESS_TOKEN_TTL_SECONDS,
// Client ID Metadata Documents: a client may present an https URL as its
// client_id instead of registering (DCR stays available). Claude's hosted
// connector re-registers a brand-new DCR client on every reconnect —
// 1,169 registrations for 80 users in the 2026-11 scan — and loses the
// login with it; its published CIMD identity gives it one stable
// client_id with nothing stored here to lose. Needs the
// `global_fetch_strictly_public` compat flag (wrangler.toml), which also
// keeps the document fetch off internal addresses. A CIMD client_id is
// shared by all users, so grants are NOT revoked per client at sign-in
// (idp/complete-mcp.ts) and such clients have no KV record to prune.
clientIdMetadataDocumentEnabled: true,
tokenExchangeCallback

  scope: ['mcp'],
  props,
  // A DCR client_id is one installation, so replacing its earlier grant is
  // right (the library default). A CIMD client_id is shared by every
  // surface of that client — the user's Desktop, web and mobile sessions
  // all sign in as the same URL and redirect URI — so revoking "the
  // existing grant" would sign the other surfaces out on each new sign-in.
  // Keep them; the nightly idle sweep retires the ones nothing refreshes.
  revokeExistingGrants: !isCimdClientId(String(authReq.clientId ?? ''))
})

