import { describe, expect, it } from 'vitest'
import { createMcpHandler, getMcpAuthContext } from 'agents/mcp/server'
import { McpServer, fromJsonSchema, isLegacyRequest } from '@modelcontextprotocol/server'
import { Client, StreamableHTTPClientTransport } from '@modelcontextprotocol/client'

const BASE = 'https://spike.test'
const seen: Array<{ era: string; method: string | null; name: string | null; proto: string | null }> = []

const handler = createMcpHandler(
  (rc) => {
    const h = rc.requestInfo?.headers
    seen.push({
      era: rc.era,
      method: h?.get('mcp-method') ?? null,
      name: h?.get('mcp-name') ?? null,
      proto: h?.get('mcp-protocol-version') ?? null
    })
    const server = new McpServer(
      { name: 'spike', version: '0.0.1' },
      { instructions: 'spike instructions' }
    )
    server.registerTool(
      'who',
      { description: 'props', inputSchema: fromJsonSchema({ type: 'object', properties: {} }) },
      async (_args, ctx) => ({
        content: [
          {
            type: 'text',
            text: JSON.stringify({
              props: getMcpAuthContext()?.props,
              clientId: ctx.http?.authInfo?.clientId,
              client: ctx.mcpReq.envelope
            })
          }
        ]
      })
    )
    server.registerTool(
      'up-x__echo',
      {
        description: 'upstream-shaped tool with raw JSON Schema',
        inputSchema: fromJsonSchema({
          type: 'object',
          properties: { msg: { type: 'string' } },
          required: ['msg']
        })
      },
      async (args, ctx) => {
        await ctx.mcpReq.notify({
          method: 'notifications/progress',
          params: { progressToken: ctx.mcpReq._meta?.progressToken ?? 'none', progress: 1 }
        })
        return { content: [{ type: 'text', text: `echo:${(args as { msg: string }).msg}` }] }
      }
    )
    return server
  },
  { route: '/mcp', legacy: 'reject', allowedHostnames: ['spike.test'] }
)

function fakeCtx() {
  return {
    waitUntil() {},
    passThroughOnException() {},
    props: { userId: 'u1', email: 'u1@test.example', role: 'member' },
    auth: {
      token: 't',
      audience: `${BASE}/mcp`,
      expiresAt: Math.floor(Date.now() / 1000) + 3600,
      scope: ['mcp'],
      userId: 'u1',
      clientId: 'https://claude.ai/oauth/mcp-oauth-client-metadata'
    }
  } as unknown as ExecutionContext
}

const viaHandler: typeof fetch = (input, init) =>
  handler(new Request(input as RequestInfo, init), {}, fakeCtx())

describe('spike: stateless handler', () => {
  it('serves a modern (2026-07-28) client end to end', async () => {
    const client = new Client(
      { name: 'spike-client', version: '1.0.0' },
      { versionNegotiation: { mode: 'auto' } } as never
    )
    await client.connect(
      new StreamableHTTPClientTransport(new URL(`${BASE}/mcp`), { fetch: viaHandler })
    )
    console.log('NEGOTIATED', client.getNegotiatedProtocolVersion?.(), client.getInstructions?.())
    const tools = await client.listTools()
    console.log('TOOLS', JSON.stringify(tools.tools.map((t) => [t.name, t.inputSchema])))
    const who = await client.callTool({ name: 'who', arguments: {} })
    console.log('WHO', JSON.stringify(who.content))
    const progress: unknown[] = []
    const echo = await client.callTool(
      { name: 'up-x__echo', arguments: { msg: 'hi' } },
      { onprogress: (p: unknown) => progress.push(p) } as never
    )
    console.log('ECHO', JSON.stringify(echo.content), 'PROGRESS', JSON.stringify(progress))
    const bad = await client.callTool({ name: 'up-x__echo', arguments: {} }).catch((e) => e)
    console.log('BADARGS', JSON.stringify(bad?.content ?? String(bad)))
    console.log('SEEN', JSON.stringify(seen))
    expect(seen.every((s) => s.era === 'modern')).toBe(true)
  })

  it('classifies a 2025 initialize as legacy and rejects it on the strict handler', async () => {
    const body = JSON.stringify({
      jsonrpc: '2.0',
      id: 1,
      method: 'initialize',
      params: {
        protocolVersion: '2025-06-18',
        capabilities: {},
        clientInfo: { name: 'old', version: '1' }
      }
    })
    const mk = () =>
      new Request(`${BASE}/mcp`, {
        method: 'POST',
        headers: { 'content-type': 'application/json', accept: 'application/json, text/event-stream' },
        body
      })
    expect(await isLegacyRequest(mk())).toBe(true)
    const res = await handler(mk(), {}, fakeCtx())
    console.log('LEGACY->STRICT', res.status, await res.text())
  })
})
