import { z } from 'zod'

/**
 * Queue message contract between producer (`usage/record.ts`) and
 * consumer (`queues/usage-consumer.ts`). Counts (bytes + tokens) are
 * pre-computed on the producer side so the consumer is pure SQL —
 * keeps queue messages bounded (Cloudflare's 128KB cap), avoids
 * shipping potentially-large tool payloads through the queue, and
 * reuses the worker's already-loaded tiktoken encoder.
 *
 * The `null` upstream id (= built-in tool like `whoami` / `search_docs`)
 * is normalised to `''` by the consumer on insert into
 * `usage_rollups_daily` so the PK column stays NOT NULL.
 */
export const UsageEventMsg = z.object({
  id: z.string(),
  ts: z.number().int(),
  userId: z.string(),
  sessionId: z.string(),
  upstreamId: z.string().nullable(),
  tool: z.string(),
  reqBytes: z.number().int().min(0),
  respBytes: z.number().int().min(0),
  reqTokens: z.number().int().min(0),
  respTokens: z.number().int().min(0),
  latencyMs: z.number().int().min(0),
  status: z.enum(['ok', 'error', 'timeout']),
  // WI-5: set when the proxy replaced an oversized response with a
  // truncation notice. Optional with a default so messages enqueued
  // before this field existed still parse on the consumer.
  truncated: z.boolean().default(false),
  // Per-error forensics (status <> 'ok' only): a coarse class + a
  // credential-scrubbed detail message, written to the raw event row and
  // surfaced in the usage error table. Nullish so events enqueued before
  // these fields existed still parse on the consumer.
  errorCode: z.string().nullish(),
  errorMessage: z.string().nullish()
})
export type UsageEventMsg = z.infer<typeof UsageEventMsg>
    // `opts.usageResp` overrides the string whose bytes/tokens are counted for
    // the response (the agent still receives `result.content` verbatim). Used
    // by `poll_task` so replaying a done job's result doesn't re-bill tokens
    // the queue consumer already counted under the real upstream tool.
    const rec = <T extends { content?: unknown; isError?: boolean }>(
      tool: string,
      args: unknown,
      exec: () => Promise<T>,
      opts?: { usageResp?: (result: T) => string | undefined }
    ): Promise<T> => {
      const t0 = Date.now()
      const reqJson = safeJson(args)
      const userId = this.props?.userId ?? ''
      const sessionId = this.getSessionId()
      // Built-ins have no upstream, so a failure is always `local_error`;
      // `errorSrc` is the raw detail (scrubbed here for the usage table).
      const finalize = (respJson: string, status: 'ok' | 'error', errorSrc?: string) =>
        this.stageUsage({
          userId,
          sessionId,
          upstreamId: null,
          tool,
          reqJson,
          respJson,
          latencyMs: Date.now() - t0,
          status,
          ...(status === 'error'
            ? {
                errorCode: 'local_error',
                errorMessage: scrubErrorForStorage(errorSrc ?? respJson)
              }
            : {})
        })
      return exec().then(
        async (result) => {
          await finalize(
            opts?.usageResp?.(result) ?? safeJson(result.content),
            result.isError ? 'error' : 'ok',
            result.isError ? errorTextFromContent(result.content) : undefined
          )
          return result
        },
        async (err) => {
          const m = errMessage(err)
          await finalize(m, 'error', m)
          throw err
        }
      )
    }

    // The built-in tools' title + description are the single source in
    // `packages/shared/src/builtin-tools.ts` (BUILTIN_TOOLS), pulled in via
    // `builtinToolMeta` so what the agent sees and what `/api/tools` lists
  private async docMarkdown(docId: string): Promise<string> {
    const snap = await readSnapshot(this.env, docId)
    if (snap) return renderBlocksToMarkdown(snap.blocks)
    const src = await readSourceMarkdown(this.env, docId)
    return src !== null ? splitFrontmatter(src).body.replace(/^\s+/, '') : ''
  }

  private async stageUsage(args: RecordUsageArgs): Promise<void> {
    try {
      stageUsageRow(this.ctx.storage.sql, buildUsageMsg(args))
      await this.schedule(USAGE_DRAIN_DELAY_SECONDS, 'flushUsageOutbox', undefined, {
        idempotent: true
      })
    } catch (err) {
      console.error(`[usage] stage failed for ${args.tool}: ${errMessage(err)}`)
    }
  }

  /**
   * Alarm callback (dispatched by the agents SDK by method name, so it
   * must stay public and keep this exact name). Drains staged usage
   * rows to USAGE_QUEUE in batches, deleting only what the queue
   * accepted, and reschedules itself while a backlog remains — on a
   * longer horizon after a send failure so a down queue can't spin the
   * DO awake. Rows survive a cut-short drain, so nothing is lost.
   */
  async flushUsageOutbox(): Promise<void> {
    const sql = this.ctx.storage.sql
    ensureOutboxTable(sql)
    try {
      const { remaining } = await drainOutbox(sql, this.env.USAGE_QUEUE)
      if (remaining > 0) {
        await this.schedule(USAGE_DRAIN_DELAY_SECONDS, 'flushUsageOutbox', undefined, {
          idempotent: true
        })
      }
    } catch (err) {
      console.error(`[usage] outbox drain failed: ${errMessage(err)}`)
      await this.schedule(USAGE_DRAIN_RETRY_SECONDS, 'flushUsageOutbox', undefined, {
        idempotent: true
      })
    }
  }
}

