export type TopUpstreamRow = UsageTopUpstream
export type TopUserRow = UsageTopUser

export interface RecentErrorRow {
  ts: number
  tool: string
  upstreamId: string // '' = built-in / local
  upstreamSlug: string | null
  code: string
  message: string | null
  userId: string
  userEmail: string | null // null for a hard-deleted user
