export async function submitAsyncJob(
  env: Env,
  ids: { userId: string; sessionId: string },
  conn: UpstreamConnection,
  upstreamToolName: string,
  args: unknown
): Promise<{ surface: AsyncSubmitSurface; respJson: string }> {
  const argsJson = safeJson(args)
  const jobKey = await hashJobKey(ids.userId, conn.id, upstreamToolName, argsJson)
  const now = Math.floor(Date.now() / 1000)
  const existing = await findLatestJobByKey(env, jobKey)

  if (existing && existing.status === 'running') {
    const age = now - existing.created_at
    if (age <= STALE_RUNNING_S) {
      return asyncSurface(
        `Task already running (job ${existing.id}, ${age}s elapsed). Call poll_task with job_id "${existing.id}" to fetch the result once ready.`
      )
    }
    // The running row's consumer invocation never completed it (age past the
    // hard call ceiling + buffer) — supersede it so a resubmit can take the
    // partial-UNIQUE running slot.
    await supersedeRunningJob(env, existing.id, now)
  } else if (
    existing &&
    existing.status === 'done' &&
    existing.result_json &&
    existing.completed_at != null &&
    now - existing.completed_at <= ASYNC_DONE_TTL_S
  ) {
    // Retry-warm: an identical call was computed recently → return it, no
    // re-run and no polling. Bill the delivery, not the payload — those
    // bytes were already counted under this tool when the consumer ran the
    // job (same rule as poll_task's done-replay branch in session-do.ts).
    return {
      surface: { isError: false, content: parseJobContent(existing.result_json) },
      respJson: `delivered: cached result of job ${existing.id} replayed to the agent (tokens billed when the job ran).`
    }
  }

  const jobId = crypto.randomUUID()
  try {
    await insertRunningJob(env, {
      id: jobId,
      userId: ids.userId,
      sessionId: ids.sessionId,
      upstreamId: conn.id,
      tool: upstreamToolName,
      jobKey,
      createdAt: now
    })
  } catch (err) {
    // Lost the race to a concurrent submit that took the running slot.
    if (/UNIQUE constraint/i.test(errMessage(err))) {
      const running = await findLatestJobByKey(env, jobKey)
      if (running && running.status === 'running') {
        return asyncSurface(
          `Task already running (job ${running.id}). Call poll_task with job_id "${running.id}".`
        )
      }
    }
    throw err
  }
  await env.JOBS_QUEUE.send({
    jobId,
    userId: ids.userId,
    upstreamId: conn.id,
    tool: upstreamToolName,
    argsJson,
    sessionId: ids.sessionId
  })
  return asyncSurface(
    `Task started (job ${jobId}). This tool runs in the background (~2-3 min) because it exceeds interactive client request timeouts. Call poll_task with job_id "${jobId}" to fetch the result, or just re-run this exact call — it returns the cached result once ready.`
  )
}
  'upstream_unreachable',
  'upstream_error',
  'local_error',
  // GitHub org-access 403s the proxy rewrites into a first-party playbook
  // (`githubOrgAccessNudge`). Split out of the generic 4xx bucket so the
  // Errors table doubles as the "who is blocked on what" list.
  'saml_sso_required',
  'org_ip_allow_list',
  'org_oauth_app_restricted',
  // ctxlayer blocked the call before it left: the caller's own credential for
  // this upstream is dead (reauth-required) or was disconnected. Recorded so
  // the Errors table doubles as the "who needs to re-authorize what" list —
  // these calls used to return before any usage row was staged.
  'credential_revoked'
] as const
export type UsageErrorCode = (typeof USAGE_ERROR_CODES)[number]

// One failed tool call for the error drill-down table. Sourced from the
// raw `usage_events` table (not the rollups), so the listing is bounded
// by the 30-day raw retention window. `upstreamId === ''` ⇒ a built-in /
// local call (the UI derives the local/remote origin from it). `code` is
// typed loosely so a worker that learns a new class can't fail an older
// SPA's response parse — the UI maps known codes and shows the rest
// verbatim. `message` is credential-scrubbed server-side (host/IP/URL
// kept); null when an error predates this column.
// `userId` / `userEmail` identify who made the call. `userId` is always
// present server-side (both source tables have a NOT NULL user_id); `userEmail`
// is null for a hard-deleted user. Both default so an older worker response
// (predating these columns) still parses on a newer SPA. Only the admin
// dashboards render them — the personal views are inherently single-user, so
// they carry the caller's own id/email and simply don't show the column.
export const UsageErrorRow = z.object({
  ts: z.number().int(), // unix seconds
  tool: z.string(),
  upstreamId: z.string(), // '' = built-in / local
  upstreamSlug: z.string().nullable(),
  code: z.string(),
  message: z.string().nullable(),
  userId: z.string().nullable().default(null),
  userEmail: z.string().nullable().default(null)
})
export type UsageErrorRow = z.infer<typeof UsageErrorRow>

// Async submit→poll analytics (WI-6). Sourced from the `async_jobs` table,
// whose rows are retained 30 days (matching usage_events; only the heavy
// result_json blob is cleared after 1 day). `durationMs` is the background run
// time of a completed job (completed_at − created_at); null while still
// running. `timedOut` is the subset of `error` whose class is 'timeout'.
// Durations are null when no job has completed yet.
export const UsageAsyncSummary = z.object({
  total: z.number().int().min(0),
  done: z.number().int().min(0),
  running: z.number().int().min(0),
  error: z.number().int().min(0),
  timedOut: z.number().int().min(0),
  avgDurationMs: z.number().int().min(0).nullable(),
  maxDurationMs: z.number().int().min(0).nullable()
})
export type UsageAsyncSummary = z.infer<typeof UsageAsyncSummary>

export const UsageAsyncJobRow = z.object({
  id: z.string(),
  tool: z.string(), // native upstream tool name
  upstreamId: z.string(),
  upstreamSlug: z.string().nullable(),
  status: z.string(), // running | done | error (loose so a new value can't fail parse)
  createdAt: z.number().int(), // unix seconds
  completedAt: z.number().int().nullable(),
  durationMs: z.number().int().min(0).nullable(),
  errorCode: z.string().nullable(),
  // See the UsageErrorRow note above — same admin-only user attribution.
  userId: z.string().nullable().default(null),
  userEmail: z.string().nullable().default(null)
})
export type UsageAsyncJobRow = z.infer<typeof UsageAsyncJobRow>

const EMPTY_ASYNC_SUMMARY: UsageAsyncSummary = {
  total: 0,
  done: 0,
  running: 0,
  error: 0,
  timedOut: 0,
  avgDurationMs: null,
  maxDurationMs: null
}
