import { Badge, Group, Text } from '@mantine/core'
import type { UsageAsyncJobRow, UsageAsyncSummary } from '@ctxlayer/shared'
import { UserCell } from './user-cell'

/**
 * Async submit→poll analytics (WI-6) for the admin usage dashboard. A summary
 * badge row + the most-recent async jobs, sourced from the `async_jobs` table.
 * A tool opts into async by being on an upstream's `asyncTools` config
 * (Admin · Upstreams → Advanced). Rows are retained 30 days like the other
 * panels; the (heavy) result body is dropped after a day.
 */

const STATUS_COLOR: Record<string, string> = {
  done: 'green',
  running: 'blue',
  error: 'red'
}

function fmtTime(tsSec: number): string {
  try {
    return new Date(tsSec * 1000).toLocaleString()
  } catch {
    return String(tsSec)
  }
}

// Background run time. Async calls are minutes-scale, so a m/s split reads
// better than raw ms.
function fmtDuration(ms: number | null): string {
  if (ms == null) return '—'
  const s = Math.round(ms / 1000)
  if (s < 60) return `${s}s`
  return `${Math.floor(s / 60)}m ${s % 60}s`
}

export function AsyncJobsTable({
  summary,
  jobs = [],
  showUser = false
}: {
  summary: UsageAsyncSummary
  jobs?: UsageAsyncJobRow[]
  // Admin dashboard sets this to attribute each job to its caller; the
  // personal view leaves it off (every row is the viewer).
  showUser?: boolean
}) {
  return (
    <>
      <Group gap="xs" mb="sm" wrap="wrap" align="center">
        <Badge variant="light" color="gray">
          {summary.total} submitted
        </Badge>
        <Badge variant="light" color="green">
          {summary.done} done
        </Badge>
        {summary.running > 0 && (
          <Badge variant="light" color="blue">
            {summary.running} running
          </Badge>
        )}
        {summary.error > 0 && (
          <Badge variant="light" color="red">
            {summary.error} error
          </Badge>
        )}
        {summary.timedOut > 0 && (
          <Badge variant="light" color="yellow">
            {summary.timedOut} timed out
          </Badge>
        )}
        {summary.avgDurationMs != null && (
          <Text fz="xs" c="dimmed">
            background run avg {fmtDuration(summary.avgDurationMs)} · max{' '}
            {fmtDuration(summary.maxDurationMs)}
          </Text>
        )}
      </Group>

      {jobs.length === 0 ? (
        <Text c="dimmed" fz="sm">
          No async tool jobs in this period. Tools opt in via an upstream&apos;s async-tools config
          (Admin · Upstreams → the upstream → Advanced).
        </Text>
      ) : (
        <table className="data-table">
          <thead>
            <tr>
              <th>Submitted</th>
              {showUser && <th>User</th>}
              <th>Tool</th>
              <th>Upstream</th>
              <th>Status</th>
              <th style={{ textAlign: 'right' }}>Duration</th>
              <th>Error</th>
            </tr>
          </thead>
          <tbody>
            {jobs.map((j) => (
              <tr key={j.id}>
                <td style={{ whiteSpace: 'nowrap' }}>
                  <Text fz="xs" c="dimmed">
                    {fmtTime(j.createdAt)}
                  </Text>
                </td>
                {showUser && (
                  <td>
                    <UserCell userId={j.userId} email={j.userEmail} />
                  </td>
                )}
                <td>
                  <code style={{ fontSize: 12 }}>{j.tool}</code>
                </td>
                <td>
                  {j.upstreamSlug ? (
                    <code style={{ fontSize: 12 }}>{j.upstreamSlug}</code>
                  ) : (
                    <Text fz="xs" c="dimmed">
                      —
                    </Text>
                  )}
                </td>
                <td>
                  <Badge size="xs" variant="light" color={STATUS_COLOR[j.status] ?? 'gray'}>
                    {j.status}
                  </Badge>
                </td>
                <td style={{ textAlign: 'right' }}>{fmtDuration(j.durationMs)}</td>
                <td>
                  {j.errorCode ? (
                    <Badge
                      size="xs"
                      variant="light"
                      color={j.errorCode === 'timeout' ? 'yellow' : 'red'}
                    >
                      {j.errorCode}
                    </Badge>
                  ) : (
                    <Text fz="xs" c="dimmed">
                      —
                    </Text>
                  )}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </>
  )
}
// Origin is derived from the row, not stored: a built-in/ctxlayer-side
// call has no upstream id, anything else involved a remote upstream.
function locusOf(row: UsageErrorRow): 'local' | 'remote' {
  return row.upstreamId === '' ? 'local' : 'remote'
}

function fmtTime(tsSec: number): string {
  try {
    return new Date(tsSec * 1000).toLocaleString()
  } catch {
    return String(tsSec)
  }
}

// Ranges longer than the 30-day raw retention — detail can't reach back
// as far as the rollup counts, so we caption the gap.
const EXCEEDS_RETENTION = new Set<UsageRange>(['90d', 'all'])

export function ErrorsTable({
  rows = [],
  range,
  showUser = false
}: {
  rows?: UsageErrorRow[]
  range: UsageRange
  // Admin dashboards set this to attribute each failure to its caller; the
  // personal view leaves it off (every row is the viewer).
  showUser?: boolean
}) {
  const [code, setCode] = useState<string>('all')
  const [locus, setLocus] = useState<string>('all')

  const codeOptions = useMemo(() => {
    const present = Array.from(new Set(rows.map((r) => r.code))).sort()
    return [
      { value: 'all', label: 'All types' },
      ...present.map((c) => ({ value: c, label: codeLabel(c) }))
    ]
  }, [rows])

  const filtered = useMemo(
    () =>
      rows.filter(
        (r) =>
          (code === 'all' || r.code === code) && (locus === 'all' || locusOf(r) === locus)
      ),
    [rows, code, locus]
  )

  const longRange = EXCEEDS_RETENTION.has(range)

  return (
    <>
      <Group gap="xs" mb="xs">
        <Select
          size="xs"
          w={170}
          data={codeOptions}
          value={code}
          onChange={(v) => setCode(v ?? 'all')}
          allowDeselect={false}
          aria-label="Filter errors by type"
        />
        <Select
          size="xs"
          w={150}
          value={locus}
          onChange={(v) => setLocus(v ?? 'all')}
          allowDeselect={false}
          aria-label="Filter errors by origin"
          data={[
            { value: 'all', label: 'Local + remote' },
            { value: 'local', label: 'Local' },
            { value: 'remote', label: 'Remote' }
          ]}
        />
      </Group>

      {rows.length === 0 ? (
        <Text c="dimmed" fz="sm">
          {longRange ? 'No errors in the last 30 days.' : 'No errors in this period.'}
        </Text>
      ) : filtered.length === 0 ? (
        <Text c="dimmed" fz="sm">
          No errors match the current filters.
        </Text>
      ) : (
        <table className="data-table">
          <thead>
            <tr>
              <th>Time</th>
              {showUser && <th>User</th>}
              <th>Tool</th>
              <th>Origin</th>
              <th>Type</th>
              <th>Detail</th>
            </tr>
          </thead>
          <tbody>
            {filtered.map((r, i) => (
              <tr key={`${r.ts}|${r.tool}|${i}`}>
                <td style={{ whiteSpace: 'nowrap' }}>
                  <Text fz="xs" c="dimmed">
                    {fmtTime(r.ts)}
                  </Text>
                </td>
                {showUser && (
                  <td>
                    <UserCell userId={r.userId} email={r.userEmail} />
                  </td>
                )}
                <td>
                  <code style={{ fontSize: 11 }}>{r.tool}</code>
                  {r.upstreamId === '' && (
                    <Text component="span" fz="xs" c="dimmed" ml={6}>
                      built-in
                    </Text>
                  )}
                </td>
                <td>
                  <Badge size="xs" variant="light" color={locusOf(r) === 'local' ? 'blue' : 'grape'}>
                    {locusOf(r)}
                  </Badge>
                </td>
                <td>
                  <Badge size="xs" variant="light" color={(CODE_COLOR as Record<string, string>)[r.code] ?? 'gray'}>
                    {codeLabel(r.code)}
                  </Badge>
                </td>
                <td>
                  {r.message ? (
                    <Text
                      fz={11}
                      style={{
                        fontFamily: 'var(--mantine-font-family-monospace)',
                        wordBreak: 'break-word'
                      }}
                    >
                      {r.message}
                    </Text>
                  ) : (
  signal?: AbortSignal
): Promise<UsageResponse> {
  const params = new URLSearchParams()
  if (opts.range) params.set('range', opts.range)
  params.set('tz', String(browserTzOffsetMin()))
  const qs = params.toString()
  const path = qs ? `/api/usage?${qs}` : '/api/usage'
  return request(path, (b) => UsageResponse.parse(b), { signal })
}

export interface FetchAdminUsageOpts extends FetchUsageOpts {
  userId?: string
  upstreamId?: string
}


const summary: UsageAsyncSummary = {
  total: 1,
  done: 1,
  running: 0,
  error: 0,
  timedOut: 0,
  avgDurationMs: 120000,
  maxDurationMs: 120000
}

const jobRow: UsageAsyncJobRow = {
  id: 'job-1',
  tool: 'gather_task_context',
  upstreamId: 'ups-driver',
  upstreamSlug: 'up-driver',
  status: 'done',
  createdAt: 1_780_000_000,
  completedAt: 1_780_000_120,
  durationMs: 120000,
  errorCode: null,
  userId: 'u-bob',
  userEmail: 'bob@example.test'
}

describe('usage tables — showUser column', () => {
  it('ErrorsTable shows the caller email only when showUser is set', () => {
    const { unmount } = wrap(<ErrorsTable rows={[errorRow]} range="30d" showUser />)
    expect(screen.getByText('User')).toBeInTheDocument()
    expect(screen.getByText('alice@example.test')).toBeInTheDocument()
    unmount()

