/**
 * SEP-2640 "Skills Extension" surface. Serves the same published skills
 * over the standardised `skill://` URI scheme plus a `skill://index.json`
 * discovery document, and advertises the `io.modelcontextprotocol/skills`
 * extension capability at initialize.
 *
 * This is additive future-proofing. The canonical surface is still
 * `list_skills` / `get_skill` + the `mcp://ctxlayer/skills/{slug}`
 * resource (skill-mcp.ts). SEP-2640 is a draft MCP extension (Resources-
 * based; in review as of 2026-06) — when hosts ship a consumer, ctxlayer
 * already speaks it. Format (SKILL.md frontmatter) is delegated to the
 * agentskills.io spec.
 * Spec: https://github.com/modelcontextprotocol/modelcontextprotocol/pull/2640
 */

import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { ResourceTemplate } from '@modelcontextprotocol/sdk/server/mcp.js'
import type { Env } from '../env'
import { listPublishedSkills } from '../db/queries/skills'
import { loadPublishedSkillMarkdown } from './skill-render'

const SKILLS_EXTENSION_ID = 'io.modelcontextprotocol/skills'
const DISCOVERY_SCHEMA = 'https://schemas.agentskills.io/discovery/0.2.0/schema.json'

export interface SkillIndexEntry {
  name: string
  type: 'skill-md'
  description: string
  url: string
}

export interface SkillIndexDoc {
  $schema: string
  skills: SkillIndexEntry[]
}

/**
 * Build the SEP-2640 `skill://index.json` discovery document from the
 * published-skill rows. Pure (no env) so it's unit-testable; each entry
/**
 * MCP resources + prompts for skills: the `mcp://ctxlayer/skills/{slug}`
 * resource template, the SEP-2640 skill resources, and one prompt per
 * published skill. (The `list_skills` / `get_skill` TOOLS are lane-neutral
 * built-ins in `mcp/builtins/skills.ts`.)
 *
 * Everything here only ever surfaces `status='published'` skills; drafts and
 * archived stay out of every MCP path.
 */

import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js'
import { ResourceTemplate } from '@modelcontextprotocol/sdk/server/mcp.js'
import type { Env } from '../env'
import { listPublishedSkills, type SkillWithUsersRow } from '../db/queries/skills'
import { loadPublishedSkillMarkdown } from './skill-render'
import { registerSkillSep2640 } from './skill-sep2640'
import {
  skillAccessAdvisory
} from '../skills/skill-requires'
import { errMessage } from '../util/errors'

export function registerSkillResources(server: McpServer, env: Env): void {
  // mcp://ctxlayer/skills/{slug} — resource template enabling resource-
  // capable agents to discover and read skills without invoking a tool.
  const template = new ResourceTemplate('mcp://ctxlayer/skills/{slug}', {
    list: async () => {
      const rows = await listPublishedSkills(env)
    // + the drafter guidance; the agent persists its draft through the
    // save_draft_skill tool. The `draft_skill` tool is the prompt's twin for
    // clients that don't render MCP prompts (both tools: mcp/builtins/).
    this.server.registerPrompt(
      'draft-skill',
      {
        title: 'Draft a skill',
        description:
          "Draft a ctxlayer skill for one or more upstreams using this org's context, then save it as your private draft. `upstreams` is a comma-separated list of slugs from list_upstreams; `intent` and `tool` are optional.",
        argsSchema: {
          upstreams: z
            .string()
            .describe('Comma-separated upstream slugs to draft against (e.g. "up-ado,up-driver").'),
          intent: z
            .string()
            .optional()
            .describe('What the skill should help with. Omit to let the model propose one.'),
          tool: z.string().optional().describe('Optional native tool name to focus the skill on.')
        }
      },
      async (args) => {
        const userId = this.props?.userId
        if (!userId) {
          return draftPromptNotice('You are not signed in to ctxlayer, so a skill cannot be drafted.')
        }
        const slugs = (args.upstreams ?? '')
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean)
        const result = await buildDraftContext(this.env, {
          upstreamSlugs: slugs,
          toolName: args.tool || undefined,
          operatorPrompt: args.intent || null,
          userId
        })
        if (!result.ok) {
          return draftPromptNotice(
            `Could not build the draft context (${result.error}). Check the upstream slug(s) with list_upstreams and try again.`
          )
        }
        return buildDraftSkillMessages(result.bundle)
      }
    )

    // ----- doc resources: mcp://ctxlayer/docs/{id} -----
    // The MCP `ResourceTemplate` lets the SDK expand `{id}` into the
    // calling URI, and our `list` callback exposes the available
    // resources so MCP clients can discover docs without guessing
    // IDs. Per-doc reads stream the snapshot rendered as markdown.
    const template = new ResourceTemplate('mcp://ctxlayer/docs/{id}', {
      list: async () => {
        const docs = await listDocs(this.env)
        return {
          resources: docs.map((d) => ({
            uri: `mcp://ctxlayer/docs/${d.id}`,
            name: d.title,
            description: d.doc_type ? `${d.slug} · ${d.doc_type}` : d.slug,
            mimeType: 'text/markdown'
          }))
        }
      }
    })

    // Hydrate proxied upstream tools alongside the built-ins. Best-effort:
    // a failure here must not block built-ins (search_docs / get_doc) from
    // serving. Each upstream's own listTools/callTool errors are caught
    // inside the registry; we only need to guard the enumeration itself.
    if (userId) {
      try {
        this.upstreamProxy = new UpstreamProxyRegistry(
          this.env,
          userId,
          (args) => this.stageUsage(args),
          this.getSessionId(),
          undefined,
          // Durable once-per-session hint state — the DO hibernates
          // between requests, so it cannot live on the registry instance.
          sqliteHintLedger(this.ctx.storage.sql),
          undefined,
          () => this.usageOrigin()
        )
        await this.upstreamProxy.init(this.server, upstreamCtx ?? undefined)
      } catch (err) {
        console.error('upstream proxy init failed:', err)
        this.upstreamProxy = null
      }
    }

    this.server.registerResource(
      'doc',
      template,
      {
        title: 'Curated documents',
        description: 'All non-deleted docs in the ctxlayer library.'
      },
      async (uri: URL, variables: { id?: string | string[] }) => {
        const idVar = variables.id
        const id = Array.isArray(idVar) ? idVar[0] : idVar
        if (!id) {
          return { contents: [{ uri: uri.toString(), text: 'missing doc id' }] }
        }
        const doc = await getDocByIdOrSlug(this.env, id)
        if (!doc) {
          return { contents: [{ uri: uri.toString(), text: `doc not found: ${id}` }] }
        }
        const markdown = await docMarkdown(this.env, doc.id)
        return {
          contents: [
            {
              uri: uri.toString(),
              mimeType: 'text/markdown',
              text: `# ${doc.title}\n\n${markdown}`
            }
          ]
        }
      }
    )
  }

  /**
   * This session's lane + client identity for the usage pages. The lane is

