    `INSERT INTO mcp_hint_ledger (user_id, client_key, upstream_id, hinted_at)
     VALUES (?1, ?2, ?3, ?4)
     ON CONFLICT(user_id, client_key, upstream_id) DO UPDATE
       SET hinted_at = excluded.hinted_at
       WHERE mcp_hint_ledger.hinted_at <= ?5
     RETURNING hinted_at`
  )
